import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
  Img,
  staticFile,
} from "remotion";
import { TransitionSeries, linearTiming } from "@remotion/transitions";
import { fade } from "@remotion/transitions/fade";

export const fps = 25;

const TRANSITION = 8;

const COLORS = {
  bg: "#0A0A0F",
  gold: "#FFB830",
  goldGlow: "#FFD700",
  red: "#E53535",
  redGlow: "#FF4444",
  blue: "#3B8BFF",
  blueGlow: "#60AAFF",
  white: "#FFFFFF",
  grey: "#2A2A35",
  dimWhite: "rgba(255,255,255,0.15)",
};

// ─── YouTube Play Button SVG Component ───────────────────────────────────────
const PlayButton: React.FC<{
  size: number;
  color?: string;
  opacity?: number;
  glowColor?: string;
  glowIntensity?: number;
}> = ({ size, color = "rgba(255,255,255,0.55)", opacity = 1, glowColor, glowIntensity = 0 }) => {
  const filterId = `glow-${Math.random().toString(36).substr(2, 9)}`;
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 100 100"
      style={{ opacity, display: "block" }}
    >
      {glowIntensity > 0 && (
        <defs>
          <filter id={filterId} x="-50%" y="-50%" width="200%" height="200%">
            <feGaussianBlur stdDeviation={glowIntensity * 12} result="blur" />
            <feComposite in="SourceGraphic" in2="blur" operator="over" />
          </filter>
        </defs>
      )}
      <rect
        x="8"
        y="8"
        width="84"
        height="84"
        rx="20"
        ry="20"
        fill={color}
        filter={glowIntensity > 0 ? `url(#${filterId})` : undefined}
      />
      <polygon
        points="38,28 72,50 38,72"
        fill={glowIntensity > 0 ? COLORS.bg : "rgba(0,0,0,0.6)"}
        opacity={glowIntensity > 0 ? 0.9 : 0.7}
      />
    </svg>
  );
};

// ─── Background ───────────────────────────────────────────────────────────────
const Background: React.FC = () => (
  <AbsoluteFill style={{ backgroundColor: COLORS.bg }} />
);

// ─── Black Screen ─────────────────────────────────────────────────────────────
const BlackScreen: React.FC = () => (
  <AbsoluteFill style={{ backgroundColor: COLORS.bg }} />
);

// ─────────────────────────────────────────────────────────────────────────────
// SCENE 1 — The Flood (0→93 frames ≈ 3.7s)
// ─────────────────────────────────────────────────────────────────────────────
const GRID_COLS = 28;
const GRID_ROWS = 16;
const TOTAL_BUTTONS = GRID_COLS * GRID_ROWS;

const Scene1Flood: React.FC = () => {
  const frame = useCurrentFrame();

  // How many buttons are revealed — accelerates over time
  const revealCurve = interpolate(frame, [0, 93], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  // Ease-in curve for acceleration feel
  const revealCount = Math.floor(
    interpolate(Math.pow(revealCurve, 1.6), [0, 1], [0, TOTAL_BUTTONS])
  );

  // Slight blur at the end — wall of content
  const blurAmount = interpolate(frame, [70, 93], [0, 1.5], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const buttonSize = 120;

  return (
    <AbsoluteFill style={{ fontFamily: "'Inter', sans-serif" }}>
      <Background />
      <AbsoluteFill
        style={{
          filter: `blur(${blurAmount}px)`,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        <div
          style={{
            display: "grid",
            gridTemplateColumns: `repeat(${GRID_COLS}, ${buttonSize}px)`,
            gridTemplateRows: `repeat(${GRID_ROWS}, ${buttonSize}px)`,
            gap: 12,
          }}
        >
          {Array.from({ length: TOTAL_BUTTONS }).map((_, i) => {
            const visible = i < revealCount;
            const popFrame = Math.floor((i / TOTAL_BUTTONS) * 93);
            const age = Math.max(0, frame - popFrame);
            const popScale = interpolate(Math.min(age, 4), [0, 4], [0, 1], {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
            });
            return (
              <div
                key={i}
                style={{
                  width: buttonSize,
                  height: buttonSize,
                  transform: `scale(${visible ? popScale : 0})`,
                  transition: "none",
                }}
              >
                {visible && (
                  <PlayButton
                    size={buttonSize}
                    color="rgba(255,255,255,0.18)"
                    opacity={interpolate(age, [0, 6], [0, 0.85], {
                      extrapolateLeft: "clamp",
                      extrapolateRight: "clamp",
                    })}
                  />
                )}
              </div>
            );
          })}
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

// ─────────────────────────────────────────────────────────────────────────────
// SCENE 2 — The Signal (0→175 frames ≈ 7s)
// ─────────────────────────────────────────────────────────────────────────────
const SIGNAL_COL = 16;
const SIGNAL_ROW = 9;

const Scene2Signal: React.FC = () => {
  const frame = useCurrentFrame();

  // Pulse cycle for the gold button
  const pulsePhase = (frame % 30) / 30;
  const pulseScale = interpolate(pulsePhase, [0, 0.5, 1], [1, 1.18, 1]);
  const pulseGlow = interpolate(pulsePhase, [0, 0.5, 1], [0.4, 1.0, 0.4]);

  // Radar rings — emit every 40 frames
  const radarRings = [0, 40, 80, 120].map((startFrame) => {
    const age = frame - startFrame;
    if (age < 0 || age > 80) return null;
    const progress = age / 80;
    return {
      scale: interpolate(progress, [0, 1], [0.05, 3.5]),
      opacity: interpolate(progress, [0, 0.3, 1], [0, 0.6, 0]),
    };
  });

  // Counter ticks up alongside signal
  const counterProgress = interpolate(frame, [15, 160], [0, 50000], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const counterDisplay = Math.round(counterProgress);

  // Dim the wall slightly
  const wallOpacity = 0.35;

  const buttonSize = 120;
  const goldIdx = SIGNAL_ROW * GRID_COLS + SIGNAL_COL;

  // Gold button entrance
  const goldEntrance = interpolate(frame, [5, 20], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Counter position — offset from gold button
  const goldX = SIGNAL_COL * (buttonSize + 12);
  const goldY = SIGNAL_ROW * (buttonSize + 12);
  const gridWidth = GRID_COLS * (buttonSize + 12);
  const gridHeight = GRID_ROWS * (buttonSize + 12);

  return (
    <AbsoluteFill style={{ fontFamily: "'Inter', sans-serif" }}>
      <Background />
      <AbsoluteFill
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        {/* Grid */}
        <div style={{ position: "relative" }}>
          <div
            style={{
              display: "grid",
              gridTemplateColumns: `repeat(${GRID_COLS}, ${buttonSize}px)`,
              gridTemplateRows: `repeat(${GRID_ROWS}, ${buttonSize}px)`,
              gap: 12,
              filter: "blur(1px)",
            }}
          >
            {Array.from({ length: TOTAL_BUTTONS }).map((_, i) => {
              const isGold = i === goldIdx;
              return (
                <div
                  key={i}
                  style={{
                    width: buttonSize,
                    height: buttonSize,
                    transform: isGold ? `scale(${pulseScale * goldEntrance})` : "scale(1)",
                    zIndex: isGold ? 10 : 1,
                    position: "relative",
                  }}
                >
                  <PlayButton
                    size={buttonSize}
                    color={isGold ? COLORS.gold : "rgba(255,255,255,0.12)"}
                    opacity={isGold ? goldEntrance : wallOpacity}
                    glowColor={isGold ? COLORS.goldGlow : undefined}
                    glowIntensity={isGold ? pulseGlow : 0}
                  />
                </div>
              );
            })}
          </div>

          {/* Radar rings centered on gold button */}
          <div
            style={{
              position: "absolute",
              left: goldX + buttonSize / 2,
              top: goldY + buttonSize / 2,
              pointerEvents: "none",
            }}
          >
            {radarRings.map(
              (ring, i) =>
                ring && (
                  <div
                    key={i}
                    style={{
                      position: "absolute",
                      width: 160,
                      height: 160,
                      borderRadius: "50%",
                      border: `3px solid ${COLORS.gold}`,
                      transform: `translate(-50%, -50%) scale(${ring.scale})`,
                      opacity: ring.opacity,
                    }}
                  />
                )
            )}
          </div>

          {/* Silent counter near the gold button */}
          <div
            style={{
              position: "absolute",
              left: goldX + buttonSize + 30,
              top: goldY + buttonSize / 2 - 40,
              opacity: interpolate(frame, [20, 40], [0, 1], {
                extrapolateLeft: "clamp",
                extrapolateRight: "clamp",
              }),
            }}
          >
            <div
              style={{
                fontSize: 56,
                fontWeight: 700,
                color: COLORS.gold,
                fontVariantNumeric: "tabular-nums",
                textShadow: `0 0 30px ${COLORS.goldGlow}`,
                letterSpacing: "-0.02em",
              }}
            >
              {counterDisplay.toLocaleString()}
            </div>
          </div>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

// ─────────────────────────────────────────────────────────────────────────────
// SCENE 3 — Opportunity Lost (0→163 frames ≈ 6.5s)
// ─────────────────────────────────────────────────────────────────────────────
const Scene3Lost: React.FC = () => {
  const frame = useCurrentFrame();

  // Gold button starts bright, then fades to grey and "sinks"
  const fadeOut = interpolate(frame, [20, 120], [1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const sinkY = interpolate(frame, [20, 130], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const sinkScale = interpolate(sinkY, [0, 1], [1.15, 0.9]);
  const glowFade = interpolate(frame, [20, 80], [0.8, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const greyProgress = interpolate(frame, [30, 120], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Color interpolation: gold → grey
  const goldRGB = [255, 184, 48];
  const greyRGB = [60, 60, 75];
  const r = Math.round(interpolate(greyProgress, [0, 1], [goldRGB[0], greyRGB[0]]));
  const g = Math.round(interpolate(greyProgress, [0, 1], [goldRGB[1], greyRGB[1]]));
  const b = Math.round(interpolate(greyProgress, [0, 1], [goldRGB[2], greyRGB[2]]));
  const buttonColor = `rgb(${r},${g},${b})`;

  const goldIdx = SIGNAL_ROW * GRID_COLS + SIGNAL_COL;
  const buttonSize = 120;

  // Pulse during first part
  const pulsePhase = (frame % 30) / 30;
  const pulseScale = frame < 40
    ? interpolate(pulsePhase, [0, 0.5, 1], [1, 1.12, 1])
    : 1;

  return (
    <AbsoluteFill style={{ fontFamily: "'Inter', sans-serif" }}>
      <Background />
      <AbsoluteFill
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        <div
          style={{
            display: "grid",
            gridTemplateColumns: `repeat(${GRID_COLS}, ${buttonSize}px)`,
            gridTemplateRows: `repeat(${GRID_ROWS}, ${buttonSize}px)`,
            gap: 12,
            filter: "blur(1px)",
          }}
        >
          {Array.from({ length: TOTAL_BUTTONS }).map((_, i) => {
            const isGold = i === goldIdx;
            if (!isGold) {
              return (
                <div key={i} style={{ width: buttonSize, height: buttonSize }}>
                  <PlayButton
                    size={buttonSize}
                    color="rgba(255,255,255,0.12)"
                    opacity={0.35}
                  />
                </div>
              );
            }
            return (
              <div
                key={i}
                style={{
                  width: buttonSize,
                  height: buttonSize,
                  transform: `scale(${sinkScale * pulseScale})`,
                  zIndex: 10,
                  position: "relative",
                  filter: glowFade > 0 ? `drop-shadow(0 0 ${glowFade * 40}px ${COLORS.goldGlow})` : undefined,
                }}
              >
                <PlayButton
                  size={buttonSize}
                  color={buttonColor}
                  opacity={Math.max(fadeOut, 0.12)}
                />
              </div>
            );
          })}
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

// ─────────────────────────────────────────────────────────────────────────────
// SCENE 4 — Damage Spreading (0→168 frames ≈ 6.7s)
// ─────────────────────────────────────────────────────────────────────────────
const RED_COL = 10;
const RED_ROW = 7;

const Scene4Damage: React.FC = () => {
  const frame = useCurrentFrame();

  const redIdx = RED_ROW * GRID_COLS + RED_COL;
  const buttonSize = 120;

  // How much infection has spread (distance from origin)
  const spreadRadius = interpolate(frame, [10, 140], [0, 35], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Red button pulse
  const pulsePhase = (frame % 25) / 25;
  const pulseScale = interpolate(pulsePhase, [0, 0.5, 1], [1, 1.22, 1]);
  const pulseGlow = interpolate(pulsePhase, [0, 0.5, 1], [0.5, 1.0, 0.5]);

  // Entrance
  const entrance = interpolate(frame, [0, 15], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill style={{ fontFamily: "'Inter', sans-serif" }}>
      <Background />
      <AbsoluteFill
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        <div
          style={{
            display: "grid",
            gridTemplateColumns: `repeat(${GRID_COLS}, ${buttonSize}px)`,
            gridTemplateRows: `repeat(${GRID_ROWS}, ${buttonSize}px)`,
            gap: 12,
            filter: "blur(0.5px)",
          }}
        >
          {Array.from({ length: TOTAL_BUTTONS }).map((_, i) => {
            const col = i % GRID_COLS;
            const row = Math.floor(i / GRID_COLS);
            const isSource = i === redIdx;
            const dist = Math.sqrt(
              Math.pow(col - RED_COL, 2) + Math.pow(row - RED_ROW, 2)
            );
            const isInfected = dist <= spreadRadius && dist > 0;
            const infectionAge = Math.max(0, spreadRadius - dist);
            const infectionProgress = Math.min(1, infectionAge / 3);

            if (isSource) {
              return (
                <div
                  key={i}
                  style={{
                    width: buttonSize,
                    height: buttonSize,
                    transform: `scale(${pulseScale * entrance})`,
                    zIndex: 10,
                    filter: `drop-shadow(0 0 ${pulseGlow * 35}px ${COLORS.redGlow})`,
                  }}
                >
                  <PlayButton
                    size={buttonSize}
                    color={COLORS.red}
                    opacity={entrance}
                  />
                </div>
              );
            }

            if (isInfected) {
              const redR = Math.round(interpolate(infectionProgress, [0, 1], [60, 229]));
              const redG = Math.round(interpolate(infectionProgress, [0, 1], [60, 53]));
              const redB = Math.round(interpolate(infectionProgress, [0, 1], [75, 53]));
              return (
                <div
                  key={i}
                  style={{
                    width: buttonSize,
                    height: buttonSize,
                  }}
                >
                  <PlayButton
                    size={buttonSize}
                    color={`rgb(${redR},${redG},${redB})`}
                    opacity={interpolate(infectionProgress, [0, 1], [0.3, 0.75])}
                  />
                </div>
              );
            }

            return (
              <div key={i} style={{ width: buttonSize, height: buttonSize }}>
                <PlayButton
                  size={buttonSize}
                  color="rgba(255,255,255,0.12)"
                  opacity={0.32}
                />
              </div>
            );
          })}
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

// ─────────────────────────────────────────────────────────────────────────────
// SCENE 5 — The Shift (0→130 frames ≈ 5.2s)
// ─────────────────────────────────────────────────────────────────────────────
const Scene5Shift: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: videoFps } = useVideoConfig();

  // Line draws left to right
  const lineProgress = spring({
    frame,
    fps: videoFps,
    delay: 8,
