              <polygon points="38,18 72,35 38,52" fill="white" />
            </svg>
          </div>

          {/* Apify logo — right */}
          <div
            style={{
              position: "absolute",
              right: 0,
              top: "50%",
              transform: `translateY(-50%)`,
              opacity: apifyProgress,
            }}
          >
            <Img
              src={staticFile("assets/apify/Apify Logo white Wordmark.svg")}
              style={{ width: 260, height: "auto" }}
            />
          </div>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

