        }}
      >
        <div style={{ position: "relative", width: 1600, height: 900 }}>
          {/* ── Main horizontal pipeline ── */}

          {/* Track */}
          <div
            style={{
              position: "absolute",
              left: 100,
              right: 400,
              top: "50%",
              transform: "translateY(-50%)",
              height: 6,
              backgroundColor: "rgba(59,139,255,0.15)",
              borderRadius: 3,
            }}
          />

          {/* Animated fill */}
          <div
            style={{
              position: "absolute",
              left: 100,
              top: "50%",
              transform: "translateY(-50%)",
              width: interpolate(pipelineProgress, [0, 1], [0, 1100]),
              height: 6,
              background: `linear-gradient(90deg, ${COLORS.blue}, ${COLORS.blueGlow})`,
              borderRadius: 3,
              boxShadow: `0 0 18px ${COLORS.blue}`,
            }}
          />

          {/* Flow dot on main pipeline */}
          {pipelineProgress > 0.5 && (
            <div
              style={{
                position: "absolute",
                left: interpolate(flowOffset, [0, 1], [110, 1180]),
                top: "50%",
                transform: "translate(-50%, -50%)",
                width: 24,
                height: 24,
                borderRadius: "50%",
                backgroundColor: COLORS.blueGlow,
                boxShadow: `0 0 35px 12px ${COLORS.blue}`,
                opacity: 0.9,
              }}
            />
          )}

          {/* YouTube icon — left */}
          <div
            style={{
              position: "absolute",
              left: 0,
              top: "50%",
              transform: `translateY(-50%)`,
              opacity: ytProgress,
            }}
          >
            <svg viewBox="0 0 100 70" width="120" height="84">
              <rect x="0" y="0" width="100" height="70" rx="16" fill="#FF0000" />
              <polygon points="38,18 72,35 38,52" fill="white" />
            </svg>
          </div>

          {/* Apify logo — center hub */}
          <div
            style={{
              position: "absolute",
              left: 1080,
              top: "50%",
              transform: "translateY(-50%)",
              opacity: apifyProgress,
              zIndex: 10,
            }}
          >
            <Img
              src={staticFile("assets/apify/Apify symbol white.svg")}
              style={{ width: 100, height: 100 }}
            />
          </div>

          {/* ── Branch lines and icons ── */}
          {BRANCHES.map((branch, i) => {
            const bp = branchProgress[i];
            const centerY = 450; // 900/2
            const branchY = centerY + branch.yOffset;
            const startX = 1130;
            const endX = 1430;
            const lineLen = endX - startX;

            return (
              <div key={i}>
                {/* Diagonal connector line */}
                <svg
                  style={{
                    position: "absolute",
                    left: 0,
                    top: 0,
                    width: 1600,
                    height: 900,
                    pointerEvents: "none",
                    overflow: "visible",
                  }}
                >
                  <line
                    x1={startX}
                    y1={centerY}
                    x2={interpolate(bp, [0, 1], [startX, endX])}
                    y2={interpolate(bp, [0, 1], [centerY, branchY])}
                    stroke={COLORS.blue}
                    strokeWidth="4"
                    opacity={bp}
                    strokeLinecap="round"
                  />
                  {/* Glow */}
                  <line
                    x1={startX}
                    y1={centerY}
                    x2={interpolate(bp, [0, 1], [startX, endX])}
                    y2={interpolate(bp, [0, 1], [centerY, branchY])}
                    stroke={COLORS.blueGlow}
                    strokeWidth="2"
                    opacity={bp * 0.5}
                    strokeLinecap="round"
                  />
                </svg>

                {/* Icon at branch end */}
                <div
                  style={{
                    position: "absolute",
                    left: endX,
                    top: branchY - iconSize / 2,
                    opacity: bp,
                    transform: `scale(${interpolate(bp, [0, 1], [0.5, 1])})`,
                    transformOrigin: "left center",
                  }}
                >
                  {branch.icon === "radar" && (
                    <RadarIcon size={iconSize} color={COLORS.blue} opacity={1} />
                  )}
                  {branch.icon === "person" && (
                    <PersonIcon size={iconSize} color={COLORS.blue} opacity={1} />
                  )}
                  {branch.icon === "data" && (
                    <DataFlowIcon size={iconSize} color={COLORS.blue} opacity={1} />
                  )}
                </div>
              </div>
            );
          })}
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

// ─────────────────────────────────────────────────────────────────────────────
// MAIN COMPOSITION
// ─────────────────────────────────────────────────────────────────────────────

// Scene durations (frames)
const S1 = 93 + TRANSITION;   // ~3.7s + overlap
const S2 = 175 + TRANSITION;  // ~7s + overlap
const S3 = 163 + TRANSITION;  // ~6.5s + overlap
const S4 = 168 + TRANSITION;  // ~6.7s + overlap
const S5 = 130 + TRANSITION;  // ~5.2s + overlap
const S6 = 205 + TRANSITION;  // ~8.2s + overlap

const OPEN = 20;
const CLOSE = 25;
const OPEN_TRANS = 20;
const CLOSE_TRANS = 15;

// Total = sum of all sequences - sum of all transitions
// sequences: OPEN(20) + S1 + S2 + S3 + S4 + S5 + S6 + CLOSE(25)
// transitions: OPEN_TRANS(20) + T×6(8×6=48) + CLOSE_TRANS(15)
export const durationInFrames =
  OPEN + S1 + S2 + S3 + S4 + S5 + S6 + CLOSE -
  (OPEN_TRANS + TRANSITION * 6 + CLOSE_TRANS);

const MainComposition: React.FC = () => {
  return (
    <TransitionSeries>
      {/* Opening black */}
      <TransitionSeries.Sequence durationInFrames={OPEN}>
        <BlackScreen />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: OPEN_TRANS })}
      />

      {/* Scene 1 — The Flood */}
      <TransitionSeries.Sequence durationInFrames={S1}>
        <Scene1Flood />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      {/* Scene 2 — The Signal */}
      <TransitionSeries.Sequence durationInFrames={S2}>
        <Scene2Signal />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      {/* Scene 3 — Opportunity Lost */}
      <TransitionSeries.Sequence durationInFrames={S3}>
        <Scene3Lost />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      {/* Scene 4 — Damage Spreading */}
      <TransitionSeries.Sequence durationInFrames={S4}>
        <Scene4Damage />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      {/* Scene 5 — The Shift */}
      <TransitionSeries.Sequence durationInFrames={S5}>
        <Scene5Shift />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      {/* Scene 6 — The Payoff */}
      <TransitionSeries.Sequence durationInFrames={S6}>
        <Scene6Payoff />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: CLOSE_TRANS })}
      />

      {/* Closing black */}
      <TransitionSeries.Sequence durationInFrames={CLOSE}>
        <BlackScreen />
      </TransitionSeries.Sequence>
    </TransitionSeries>
  );
};

export default MainComposition;
